-- Seed only when the DB is empty. Time slots / schedules are NOT inserted: they are generated by the engine from the scenario config.
SELECT v.name, v.description, jsonb_build_object('startDate', to_char(current_date,'YYYY-MM-DD'),'days',7,'startTime','17:00','slotDuration',4,'peoplePerPost',v.ppp,'dutyHours',v.duty,'withdrawalHours',4,'alternateDays',true,'rotationEnabled',true,'nightStart','22:00','nightEnd','06:00','minimumRestHours',8,'maximumDutyHoursPerDay',null,'maximumDutyHoursPerPeriod',null)
FROM (VALUES ('Scenario A','3 คน/จุด เวร 8 ชม.',3,8),('Scenario B','2 คน/จุด เวร 8 ชม.',2,8),('Scenario C','2 คน/จุด เวร 12 ชม. (ทดลอง)',2,12)) AS v(name,description,ppp,duty)
WHERE NOT EXISTS (SELECT 1 FROM ds_scenarios);
